// spec.ErrNoHandlers for a server that takes none. Declare.HandleCaptureSnapshot is
// the handler at construction; this setter changes it at run time.
func (s *Server) HandleCaptureSnapshot(fn func(ctx context.Context, req CaptureSnapshotRequest) (CaptureSnapshotResponse, error)) error {
	return spec.HandleOn(s.Underlying(), CmdCaptureSnapshot, fn)
}

// Declare is the declaration of the CameraAvStreamManagement cluster on a device:
// device.New<Type> and device.FromSpec take it, and every field is
// optional — the zero value mounts the cluster (an optional one too)
// with the kit's default server and the device type's defaults. A
// device takes one Declare per cluster.
type Declare struct {
	// Initial is the state the server starts with, over the device
	// type's defaults; an optional attribute it sets is served.
	Initial Patch
	// Features is the FeatureMap selection; zero is the device type's.
	Features Feature
	// Commands are optional commands the server accepts beyond the
	// ones the selection mandates: the kit's server carries them out
	// (through its port), a Handle field below handles one in its place.
	Commands []uint32
	// OnWrite vetoes a controller's write before it is stored
	// (Server.OnWrite); it runs inline.
	OnWrite func(ctx context.Context, next State, attrID uint32) error
	// HandleAudioStreamAllocate handles the AudioStreamAllocate command in place of the server
	// (Server.HandleAudioStreamAllocate), inline; an optional command it handles is accepted.
	HandleAudioStreamAllocate func(ctx context.Context, req AudioStreamAllocateRequest) (AudioStreamAllocateResponse, error)
	// HandleAudioStreamDeallocate handles the AudioStreamDeallocate command in place of the server
	// (Server.HandleAudioStreamDeallocate), inline; an optional command it handles is accepted.
	HandleAudioStreamDeallocate func(ctx context.Context, req AudioStreamDeallocateRequest) (struct{}, error)
	// HandleVideoStreamAllocate handles the VideoStreamAllocate command in place of the server
	// (Server.HandleVideoStreamAllocate), inline; an optional command it handles is accepted.
	HandleVideoStreamAllocate func(ctx context.Context, req VideoStreamAllocateRequest) (VideoStreamAllocateResponse, error)
	// HandleVideoStreamModify handles the VideoStreamModify command in place of the server
	// (Server.HandleVideoStreamModify), inline; an optional command it handles is accepted.
	HandleVideoStreamModify func(ctx context.Context, req VideoStreamModifyRequest) (struct{}, error)
	// HandleVideoStreamDeallocate handles the VideoStreamDeallocate command in place of the server
	// (Server.HandleVideoStreamDeallocate), inline; an optional command it handles is accepted.
	HandleVideoStreamDeallocate func(ctx context.Context, req VideoStreamDeallocateRequest) (struct{}, error)
	// HandleSnapshotStreamAllocate handles the SnapshotStreamAllocate command in place of the server
	// (Server.HandleSnapshotStreamAllocate), inline; an optional command it handles is accepted.
	HandleSnapshotStreamAllocate func(ctx context.Context, req SnapshotStreamAllocateRequest) (SnapshotStreamAllocateResponse, error)
	// HandleSnapshotStreamModify handles the SnapshotStreamModify command in place of the server
	// (Server.HandleSnapshotStreamModify), inline; an optional command it handles is accepted.
	HandleSnapshotStreamModify func(ctx context.Context, req SnapshotStreamModifyRequest) (struct{}, error)
	// HandleSnapshotStreamDeallocate handles the SnapshotStreamDeallocate command in place of the server
	// (Server.HandleSnapshotStreamDeallocate), inline; an optional command it handles is accepted.
	HandleSnapshotStreamDeallocate func(ctx context.Context, req SnapshotStreamDeallocateRequest) (struct{}, error)
	// HandleSetStreamPriorities handles the SetStreamPriorities command in place of the server
	// (Server.HandleSetStreamPriorities), inline; an optional command it handles is accepted.
	HandleSetStreamPriorities func(ctx context.Context, req SetStreamPrioritiesRequest) (struct{}, error)
	// HandleCaptureSnapshot handles the CaptureSnapshot command in place of the server
	// (Server.HandleCaptureSnapshot), inline; an optional command it handles is accepted.
	HandleCaptureSnapshot func(ctx context.Context, req CaptureSnapshotRequest) (CaptureSnapshotResponse, error)
	// HostServer is the host's own server for the cluster, mounted in
	// place of the kit's — also for a cluster the device type does not
	// list. The hooks above go on it; Initial, Features and the ports are
	// the kit's server's and are refused beside it.
	HostServer contract.ClusterServer
}

// ClusterID implements device.Declaration: the cluster declared.
func (Declare) ClusterID() uint32 { return ClusterID }

// ClusterDeclaration implements device.Declaration: the declaration in
// the form the device kit applies it.
func (d Declare) ClusterDeclaration() spec.ClusterDeclaration {
	decl := spec.ClusterDeclaration{Cluster: ClusterID, Initial: d.Initial.AttributeValues(), Server: d.HostServer, Ports: d}
	if d.OnWrite != nil {
		decl.Attach = d.attach
	}
	decl.Features, decl.HasFeatures = uint32(d.Features), d.Features != 0
	decl.Elements.Commands = append(decl.Elements.Commands, d.Commands...)
	if d.HandleAudioStreamAllocate != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAudioStreamAllocate)
		decl.Attach = d.attach
	}
	if d.HandleAudioStreamDeallocate != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdAudioStreamDeallocate)
		decl.Attach = d.attach
	}
	if d.HandleVideoStreamAllocate != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdVideoStreamAllocate)
		decl.Attach = d.attach
	}
	if d.HandleVideoStreamModify != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdVideoStreamModify)
		decl.Attach = d.attach
	}
	if d.HandleVideoStreamDeallocate != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdVideoStreamDeallocate)
		decl.Attach = d.attach
	}
	if d.HandleSnapshotStreamAllocate != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSnapshotStreamAllocate)
		decl.Attach = d.attach
	}
	if d.HandleSnapshotStreamModify != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSnapshotStreamModify)
		decl.Attach = d.attach
	}
	if d.HandleSnapshotStreamDeallocate != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSnapshotStreamDeallocate)
		decl.Attach = d.attach
	}
	if d.HandleSetStreamPriorities != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdSetStreamPriorities)
		decl.Attach = d.attach
	}
	if d.HandleCaptureSnapshot != nil {
		decl.Elements.Commands = append(decl.Elements.Commands, CmdCaptureSnapshot)
		decl.Attach = d.attach
	}
	return decl
}

// attach installs the declaration's veto and handlers on srv; the
// error names each one the server refused.
func (d Declare) attach(srv contract.ClusterServer) error {
	s := Wrap(srv)
	var errs []error
	if d.OnWrite != nil {
		errs = append(errs, spec.HookError(Name, "OnWrite", s.OnWrite(d.OnWrite)))
	}
	if d.HandleAudioStreamAllocate != nil {
		errs = append(errs, spec.HookError(Name, "HandleAudioStreamAllocate", s.HandleAudioStreamAllocate(d.HandleAudioStreamAllocate)))
	}
	if d.HandleAudioStreamDeallocate != nil {
		errs = append(errs, spec.HookError(Name, "HandleAudioStreamDeallocate", s.HandleAudioStreamDeallocate(d.HandleAudioStreamDeallocate)))
	}
	if d.HandleVideoStreamAllocate != nil {
		errs = append(errs, spec.HookError(Name, "HandleVideoStreamAllocate", s.HandleVideoStreamAllocate(d.HandleVideoStreamAllocate)))
	}
	if d.HandleVideoStreamModify != nil {
		errs = append(errs, spec.HookError(Name, "HandleVideoStreamModify", s.HandleVideoStreamModify(d.HandleVideoStreamModify)))
	}
	if d.HandleVideoStreamDeallocate != nil {
		errs = append(errs, spec.HookError(Name, "HandleVideoStreamDeallocate", s.HandleVideoStreamDeallocate(d.HandleVideoStreamDeallocate)))
	}
	if d.HandleSnapshotStreamAllocate != nil {
		errs = append(errs, spec.HookError(Name, "HandleSnapshotStreamAllocate", s.HandleSnapshotStreamAllocate(d.HandleSnapshotStreamAllocate)))
	}
	if d.HandleSnapshotStreamModify != nil {
		errs = append(errs, spec.HookError(Name, "HandleSnapshotStreamModify", s.HandleSnapshotStreamModify(d.HandleSnapshotStreamModify)))
	}
	if d.HandleSnapshotStreamDeallocate != nil {
		errs = append(errs, spec.HookError(Name, "HandleSnapshotStreamDeallocate", s.HandleSnapshotStreamDeallocate(d.HandleSnapshotStreamDeallocate)))
	}
	if d.HandleSetStreamPriorities != nil {
		errs = append(errs, spec.HookError(Name, "HandleSetStreamPriorities", s.HandleSetStreamPriorities(d.HandleSetStreamPriorities)))
	}
	if d.HandleCaptureSnapshot != nil {
		errs = append(errs, spec.HookError(Name, "HandleCaptureSnapshot", s.HandleCaptureSnapshot(d.HandleCaptureSnapshot)))
	}
	return errors.Join(errs...)
}
